import numpy as np

def lstsq_normal(A, b):
    A, b = np.asarray(A, dtype=float), np.asarray(b, dtype=float)
    return np.linalg.solve(A.T @ A, A.T @ b)

def lstsq_qr(A, b):
    A, b = np.asarray(A, dtype=float), np.asarray(b, dtype=float)
    Q, R = np.linalg.qr(A)
    y = Q.T @ b
    n = R.shape[1]
    x = np.zeros(n)
    for k in range(n - 1, -1, -1):
        x[k] = (y[k] - R[k, k + 1:] @ x[k + 1:]) / R[k, k]
    return x

